+pub fn hex_to_bytes(s: &str) -> Result<Vec<u8>, QuoteVerificationError> {
+    if s.len() % 2 != 0 {
+        return Err(QuoteVerificationError::InvalidQeIdentity);
+    }
+    let mut bytes = Vec::with_capacity(s.len() / 2);
+    for i in (0..s.len()).step_by(2) {
+        let byte = u8::from_str_radix(&s[i..i + 2], 16)
+            .map_err(|_| QuoteVerificationError::InvalidQeIdentity)?;
+        bytes.push(byte);
+    }
+    Ok(bytes)
+}
+
